        run,
        seq: EventSeq::new(seq),
        workflow: digest,
    });
    seq = seq.saturating_add(1);

    // Step 0: start, write slots, succeed
    events.push(JournalEvent::StepStarted {
        run,
        seq: EventSeq::new(seq),
        step: StepIdx::new(0),
        attempt: 1,
    });
    seq = seq.saturating_add(1);

    events.push(JournalEvent::SlotWrittenEvent {
        run,
        seq: EventSeq::new(seq),
        slot: SlotIdx::new(0),
        value: None,
        extra: None,
        attempt: 1,
    });
    seq = seq.saturating_add(1);

    events.push(JournalEvent::SlotWrittenEvent {
        run,
        seq: EventSeq::new(seq),
        slot: SlotIdx::new(1),
