        JournalEvent::StepStarted {
            run,
            seq: vb_storage::EventSeq::new(2),
            step: StepIdx::ZERO,
            attempt: 1,
        },
        JournalEvent::AskScheduledEvent {
            run,
            seq: vb_storage::EventSeq::new(3),
            step: StepIdx::ZERO,
            attempt: 1,
        },
