    let events = journal.events_for_run(run).map_err(|e| e.to_string())?;
    for event in events.iter().rev() {
        if let JournalEvent::RetryCheckpoint { payload, .. } = event {
            let decoded = run_checkpoint::decode_checkpoint_payload(payload)
